def compute(vars):
    old_total = vars["v1"]
    new_total = vars["v2"]
    old_zyla = vars["v3"]
    new_zyla = vars["v4"]

    total_decrease = old_total - new_total
    zyla_decrease = old_zyla - new_zyla

    if total_decrease == 0:
        return None

    value = (zyla_decrease / total_decrease) * 100

    return {
        "value": value,
        "trace": {
            "old_total_revenue": old_total,
            "new_total_revenue": new_total,
            "total_revenue_decrease": total_decrease,
            "old_zyla_revenue": old_zyla,
            "new_zyla_revenue": new_zyla,
            "zyla_revenue_decrease": zyla_decrease,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }

