                "scale": "million",
                "unit": None
            }
        }
    }

def compute(vars):
    net_2018 = vars["v1"]
    accumulated_depreciation_2018 = vars["v2"]
    net_2019 = vars["v3"]
    accumulated_depreciation_2019 = vars["v4"]

    if accumulated_depreciation_2018 == 0 or accumulated_depreciation_2019 == 0:
        return None

    ratio_2018 = net_2018 / accumulated_depreciation_2018
    ratio_2019 = net_2019 / accumulated_depreciation_2019

    if ratio_2018 == 0:
        return None

    change_ratio = (ratio_2019 - ratio_2018) / ratio_2018
    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "ratio_2018": ratio_2018,
            "ratio_2019": ratio_2019,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }

